#include <iostream>
#include <vector>
#include <numeric>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> l(n);
    long long total_circ = 0;
    for (int i = 0; i < n; ++i) {
        cin >> l[i];
        total_circ += l[i];
    }

    if (total_circ % 2 != 0) {
        cout << "N\n";
        return 0;
    }

    long long half = total_circ / 2;

    vector<long long> prefix(n);
    prefix[0] = 0;
    for (int i = 1; i < n; ++i) {
        prefix[i] = prefix[i - 1] + l[i - 1];
    }

    int pairs = 0;
    int j = 0;
    for (int i = 0; i < n; ++i) {
        while (j < n && prefix[j] - prefix[i] < half) {
            j++;
        }
        if (j < n && prefix[j] - prefix[i] == half) {
            pairs++;
        }
    }

    if (pairs >= 2) {
        cout << "S\n";
    } else {
        cout << "N\n";
    }

    return 0;
}
